package net.rec0de.android.watchwitch.servicehandlers

import net.rec0de.android.watchwitch.Log
import net.rec0de.android.watchwitch.WatchState
import net.rec0de.android.watchwitch.alloy.AlloyController
import net.rec0de.android.watchwitch.alloy.AlloyHandler
import net.rec0de.android.watchwitch.alloy.AlloyMessage
import net.rec0de.android.watchwitch.alloy.AlloyService
import net.rec0de.android.watchwitch.alloy.ProtobufMessage
import net.rec0de.android.watchwitch.bitmage.fromHex
import net.rec0de.android.watchwitch.bitmage.hex
import net.rec0de.android.watchwitch.decoders.bplist.BPArray
import net.rec0de.android.watchwitch.decoders.bplist.BPAsciiString
import net.rec0de.android.watchwitch.decoders.bplist.BPInt
import net.rec0de.android.watchwitch.decoders.bplist.BPNull
import net.rec0de.android.watchwitch.decoders.bplist.BPSDict
import net.rec0de.android.watchwitch.decoders.bplist.BPUid
import net.rec0de.android.watchwitch.decoders.protobuf.ProtoBuf
import net.rec0de.android.watchwitch.decoders.protobuf.ProtoI64
import net.rec0de.android.watchwitch.decoders.protobuf.ProtoLen
import net.rec0de.android.watchwitch.decoders.protobuf.ProtoString
import net.rec0de.android.watchwitch.decoders.protobuf.ProtoVarInt
import net.rec0de.android.watchwitch.decoders.protobuf.ProtobufParser
import net.rec0de.android.watchwitch.devices.Watch
import net.rec0de.android.watchwitch.servicehandlers.health.HealthSync

object PBBridge : AlloyService {

    private const val TOPIC = "com.apple.private.alloy.pbbridge"
    override val handlesTopics = listOf(TOPIC)
    override fun acceptsMessageType(msg: AlloyMessage) = msg is ProtobufMessage
    override fun acceptsLocalDeviceRole(device: AlloyService.Device) = device == AlloyService.Device.WATCH
    private const val TAG = "PBBridge"

    override fun receiveMessage(msg: AlloyMessage, handler: AlloyHandler) {
        msg as ProtobufMessage

        val decoded = try {
            val decoded = ProtobufParser().parse(msg.payload)
            Log.d(TAG, "got message type ${msg.type}: $decoded")
            decoded
        }
        catch (e: Exception) {
            Log.d(TAG, "expected Protobuf payload, got ${msg.payload.hex()}")
            return
        }

        /*
            Watch-sent types:
            1: gizmoBecameAvailableWantsConfirmation:
            2: sendProxyActivationRequest:
            3: gizmoDidBeginActivating:
            4, 0x15: gizmoDidFinishActivating:
            5: getCompanionLanguage:
            6: getCompanionRegion:
            7: gizmoDidEndPasscodeCreation:
            8: getSiriState:
            0x0f: handleOfflineTermsResponse:
            0x10: handlePerformanceResults:
            0x11: gizmoFailedToCreatePasscode:
            0x0c: gizmoActivationFailed:
            0x0d: gizmoDidEndUnlockPairing:
            0x0e: handleWarrantySentinelResponse:
            0x1c: gizmoDidEndPasscodeChange:
            0x12: watchDidPrepareForInitialSync:
            0x13: gizmoDidBeginUnlockPairing:
            0x14: watchDidRespondWithLanguageAndLocaleStatus:
            0x16: watchDidIngestWirelessCredentials:
            0x17: watchDidPrepareForForcedSU:
            0x1b: handleRemoteActivationDetails:
            0x1e: acknowledgeBuysOnWatchCredentialIngestion:
         */

        when(msg.type) {

            3 -> {
                val progress = (decoded.objs[2]!!.first() as ProtoI64).asDate(appleEpoch = true)
                val unk = (decoded.objs[1]!!.first() as ProtoVarInt).value.toInt()
                Log.d(TAG, "got progress: $progress ($unk)")
            }
            14 -> ackNameChange(msg.messageUUID.toString(), decoded, handler)
            16 -> sendToS(msg.messageUUID.toString(), handler)

            21 -> {
                Log.d(TAG, "sending empty reply message")
                handler.sendProtobuf("".fromHex(), TOPIC, 18, isResponse = true, responseIdentifier = msg.messageUUID.toString())
                Anisette.requestAnisetteData(handler)
                HealthSync.activationRestore()
            }
            25 -> {
                sendDoubleValue(handler)
            }
            29 -> sendAKDevice(msg.messageUUID.toString(), handler)
        }

    }

    fun readyForBridgeInit() {
        val handler = AlloyController.getHandlerForChannel("UTunDelivery-Default-Urgent-D")!!
        sendActivationComplete(handler)
    }

    private fun sendActivationComplete(handler: AlloyHandler) {
        Log.d(TAG, "sending activation complete")
        WatchState.incrementProgress()
        WatchState.setPairingStage("sent PBBridge activation complete")
        handler.sendProtobuf("".fromHex(), TOPIC, 4, isResponse = false)
    }

    private fun sendDoubleValue(handler: AlloyHandler) {
        Log.d(TAG, "sending double value 1.0")
        val data = ProtoBuf.singles(mapOf(1 to ProtoI64(1.0)))
        handler.sendProtobuf(data.renderStandalone(), TOPIC, 20, isResponse = false)
    }

    private fun ackNameChange(responseID: String, data: ProtoBuf, handler: AlloyHandler) {
        val name = (data.objs[5]?.first() as ProtoLen?)?.asString()
        val language = (data.objs[4]!!.first() as ProtoString).stringValue
        val languages = data.objs[3]!!
        Log.d(TAG, "handling name change to $name")

        if(name != null) {
            WatchState.addStolenInfo(setOf("Name: $name", "Lang: $language"))
            Watch.NAME = name
        }

        val reply = ProtoBuf(mapOf(
            1 to listOf(ProtoVarInt(0)),
            3 to languages,
            4 to listOf(ProtoString(language))
        ))

        handler.sendProtobuf(reply.renderStandalone(), TOPIC, 14, isResponse = true, responseIdentifier = responseID)
    }

    private fun sendToS(responseID: String, handler: AlloyHandler) {
        Log.d(TAG, "sending ToS")
        val data = ProtoBuf.singles(mapOf(1 to ProtoLen("".fromHex())))
        handler.sendProtobuf(data.renderStandalone(), TOPIC, 15, isResponse = true, responseIdentifier = responseID, compress = false)
    }

    private fun sendAKDevice(responseID: String, handler: AlloyHandler) {
        //handler.sendData(byteArrayOf(), "com.apple.private.alloy.connectivity.monitor", UUID.randomUUID())

        Log.d(TAG, "sending AKDevice info")

        val bplist = "".fromHex()

        val archive = BPSDict(mapOf(
            "_locale" to BPSDict(mapOf(
                "\$class" to BPSDict(mapOf(
                    "\$classes" to BPArray(listOf(BPAsciiString("NSAutoLocale"), BPAsciiString("NSLocale"), BPAsciiString("NSObject"))),
                    "\$classname" to BPAsciiString("NSAutoLocale")
                ))
            )),
            "_linkType" to BPInt(1),
            "_enclosureColor" to BPNull,
            "_housingColor" to BPInt(2),
            "_uniqueDeviceIdentifier" to BPAsciiString("00008006-001E3034118A801D"),
            "_MLBSerialNumber" to BPNull,
            "_ROMAddress" to BPNull,
            "_modelNumber" to BPAsciiString(Watch.MODEL_NUMBER),
            "_serverFriendlyDescription" to BPAsciiString("<${Watch.HW_VERSION}> <${Watch.OS_NAME};${Watch.OS_VERSION};${Watch.BUILD}> <com.apple.AuthKit/1 (com.apple.nanobuddy/1.0)>"),
            "_coverGlassColor" to BPInt(1),
            "\$class" to BPSDict(mapOf(
                "\$classes" to BPArray(listOf(BPAsciiString("AKDevice"), BPAsciiString("NSObject"))),
                "\$classname" to BPAsciiString("AKDevice")
            )),
            "_backingColor" to BPInt(0),
            "_color" to BPAsciiString("1"),
        ))

        val encoded = BPSDict(mapOf(
            "\$objects" to BPArray(listOf(
                BPAsciiString("\$null"),
                BPSDict(mapOf(
                    "_locale" to BPUid.fromInt(0x08),
                    "_linkType" to BPUid.fromInt(0x05),
                    "_enclosureColor" to BPUid.fromInt(0x00),
                    "_housingColor" to BPUid.fromInt(0x06),
                    "_uniqueDeviceIdentifier" to BPUid.fromInt(0x02),
                    "_MLBSerialNumber" to BPUid.fromInt(0x00),
                    "_ROMAddress" to BPUid.fromInt(0x00),
                    "_modelNumber" to BPUid.fromInt(0x0a),
                    "_serverFriendlyDescription" to BPUid.fromInt(0x03),
                    "_coverGlassColor" to BPUid.fromInt(0x05),
                    "\$class" to BPUid.fromInt(0x0b),
                    "_backingColor" to BPUid.fromInt(0x07),
                    "_color" to BPUid.fromInt(0x04),
                )),
                BPAsciiString("00008006-001E3034118A801D"),
                BPAsciiString("<${Watch.HW_VERSION}> <${Watch.OS_NAME};${Watch.OS_VERSION};${Watch.BUILD}> <com.apple.AuthKit/1 (com.apple.nanobuddy/1.0)>"),
                BPAsciiString("1"),
                BPInt(1),
                BPInt(2),
                BPInt(0),
                BPSDict(mapOf("\$class" to BPUid.fromInt(9))),
                BPSDict(mapOf(
                    "\$classes" to BPArray(listOf(BPAsciiString("NSAutoLocale"), BPAsciiString("NSLocale"), BPAsciiString("NSObject"))),
                    "\$classname" to BPAsciiString("NSAutoLocale")
                )),
                BPAsciiString(Watch.MODEL_NUMBER),
                BPSDict(mapOf(
                    "\$classes" to BPArray(listOf(BPAsciiString("AKDevice"), BPAsciiString("NSObject"))),
                    "\$classname" to BPAsciiString("AKDevice")
                ))
            )),
            "\$version" to BPInt(100000),
            "\$archiver" to BPAsciiString("NSKeyedArchiver"),
            "\$top" to BPSDict(mapOf("root" to BPUid.fromInt(1)))
        ))

        val data = ProtoBuf.singles(mapOf(
            1 to ProtoLen(encoded.renderAsTopLevelObject())
        ))
        handler.sendProtobuf(data.renderStandalone(), TOPIC, 25, isResponse = true, responseIdentifier = responseID)
    }
}